/bin/bash -lc "cat > src/util/checkoutRequest.mjs <<'EOF'
export function buildCheckoutRequest({
  cartCode,
  shippingOptionId,
  currency,
  paymentToken,
  paymentModule,
  amount,
  agreedToTerms,
  comments,
}) {
  return {
    method: \"POST\",
    path: "'`cart/${cartCode}/checkout`,
    body: {
      quoteId: shippingOptionId,
      currency,
      termsAccepted: agreedToTerms,
      orderNote: comments,
      payment: {
        paymentType: "CREDITCARD",
        transactionType: "CAPTURE",
        processor: paymentModule,
        cardToken: paymentToken,
        amount,
      },
    },
  };
}
EOF
node --input-type=module -e "
import { buildCheckoutRequest } from '"'./src/util/checkoutRequest.mjs';
const r = buildCheckoutRequest({
  cartCode: 'abc123',
  shippingOptionId: 42,
  currency: 'USD',
  paymentToken: 'tok_123',
  paymentModule: 'stripe',
  amount: '19.99',
  agreedToTerms: true,
  comments: 'leave at door',
});
console.log(JSON.stringify(r, null, 2));
\""
